/* ── layout ────────────────────────────────────────────────────────────── */
function layout() {
  var plotH = state.showPlot ? 195 : 0, boxes = [], v = state.view;
  if (v === 'stacked') {
    VBW = 600; VBH = 1000 + plotH;
    boxes = [[PANEL_A, { x: 18, y: 58, w: VBW - 36, h: 400 }], [PANEL_B, { x: 18, y: 512, w: VBW - 36, h: 430 }]];
  } else if (v === 'both') {
    VBW = 900; VBH = 560 + plotH;
    var gp = 22, w = (VBW - 36 - gp) / 2;
    boxes = [[PANEL_A, { x: 18, y: 56, w: w, h: 430 }], [PANEL_B, { x: 18 + w + gp, y: 56, w: w, h: 430 }]];
  } else {
    VBW = 740; VBH = 600 + plotH;
    var cfg = (v === 'a') ? PANEL_A : PANEL_B;
    boxes = [[cfg, { x: 20, y: 56, w: VBW - 40, h: 470 }]];
  }
  plotBox = state.showPlot ? { x: 72, y: VBH - plotH + 30, w: VBW - 132, h: plotH - 78 } : null;

  figDraw.clear();
  figDraw.viewbox(0, 0, VBW, VBH);
  figDraw.rect(VBW, VBH).move(0, 0).fill('#ffffff');

  gStatic = figDraw.group();
  txt(gStatic, 'Vectors not to scale', VBW / 2, 26, 21, { style: 'italic', halo: false });

  panels = [];
  boxes.forEach(function (bx) {
    var p = mkPanel(bx[0], bx[1]);
    panels.push(p);
    drawPanelStatic(gStatic, p);
    txt(gStatic, bx[0].caption, bx[1].x + bx[1].w / 2, bx[1].y + bx[1].h + 22, 20, { style: 'italic', halo: false });
  });

  gCurve = figDraw.group();
  gDyn = figDraw.group();
  gPlot = figDraw.group();
  drawCurves();
  drawDynamic();
}

